export class PruneEngine {
  private entries: Map<string, { updatedAt: number }> = new Map()
  prune(limit: number): void {
    if (this.entries.size <= limit) { return }
    let oldest = Number.MAX_SAFE_INTEGER
    let selected: string | undefined = undefined
    for (const [key, value] of this.entries) {
      if (value.updatedAt < oldest) { oldest = value.updatedAt; selected = key }
    }
    if (selected !== undefined) { this.entries.delete(selected) }
  }
}

